	"time"
)

func main() {
	srv := &http.Server{Addr: "127.0.0.1:0", Handler: http.NewServeMux()}
	go func() {
		if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			fmt.Println("服务异常:", err)
		}
	}()
	time.Sleep(20 * time.Millisecond)
	fmt.Println("关闭:", srv.Close())
}

package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
	"time"
)

type User struct {
	ID   int    `json:"id"`
	Name string `json:"name"`
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /users/{id}", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(User{ID: 1, Name: r.PathValue("id")})
	})
	mux.HandleFunc("POST /users", func(w http.ResponseWriter, r *http.Request) {
		var u User
		if err := json.NewDecoder(r.Body).Decode(&u); err != nil {
			http.Error(w, "JSON 不合法", http.StatusBadRequest)
			return
		}
		w.WriteHeader(http.StatusCreated)
		_ = json.NewEncoder(w).Encode(u)
	})

	// 用 Recorder 直接调 handler，不监听端口
	getRec := httptest.NewRecorder()
	mux.ServeHTTP(getRec, httptest.NewRequest("GET", "/users/42", nil))
	fmt.Println("GET:", getRec.Code, strings.TrimSpace(getRec.Body.String()))

	postRec := httptest.NewRecorder()
	postReq := httptest.NewRequest("POST", "/users", strings.NewReader(`{"id":7,"name":"张三"}`))
	mux.ServeHTTP(postRec, postReq)
	fmt.Println("POST:", postRec.Code, strings.TrimSpace(postRec.Body.String()))

	client := &http.Client{Timeout: 2 * time.Second}
	srv := &http.Server{Handler: mux, ReadHeaderTimeout: 5 * time.Second}
	fmt.Println("client 超时:", client.Timeout, "server 有 handler:", srv.Handler != nil)
}
